package com.google.javascript.rhino;

import com.google.common.base.Preconditions;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class IR_tryFinally_TriageGen0Test {

    @Test
    public void testTryFinallySuccess() {
        // Prepare valid inputs: both must be label names according to Preconditions
        Node tryBody = IR.labelName("tryLabel");
        Node finallyBody = IR.labelName("finallyLabel");

        // Execute
        Node result = IR.tryFinally(tryBody, finallyBody);

        // Assertions
        assertNotNull("Result should not be null", result);
        assertEquals("Token should be TRY", Token.TRY, result.getType());
        assertEquals("Try body should match input", tryBody, result.getFirstChild());
        assertEquals("Finally body should match input", finallyBody, result.getLastChild());

        // The middle child is catchBody, which is a copy of tryBody info
        Node catchBody = result.getSecondChild();
        assertNotNull("Catch body should be created", catchBody);
        assertTrue("Catch body should be a block-like node", catchBody.isBlock());
    }

    @Test(expected = IllegalStateException.class)
    public void testTryFinallyThrowsWhenTryBodyIsNotLabelName() {
        // tryBody is a generic node, not a label name
        Node tryBody = IR.block();
        Node finallyBody = IR.labelName("finallyLabel");

        // Should throw IllegalStateException due to Preconditions.checkState
        IR.tryFinally(tryBody, finallyBody);
    }

    @Test(expected = IllegalStateException.class)
    public void testTryFinallyThrowsWhenFinallyBodyIsNotLabelName() {
        // finallyBody is a generic node, not a label name
        Node tryBody = IR.labelName("tryLabel");
        Node finallyBody = IR.block();

        // Should throw IllegalStateException due to Preconditions.checkState
        IR.tryFinally(tryBody, finallyBody);
    }

    @Test(expected = IllegalStateException.class)
    public void testTryFinallyThrowsWhenBothAreNotLabelNames() {
        Node tryBody = IR.block();
        Node finallyBody = IR.block();

        // Should throw IllegalStateException
        IR.tryFinally(tryBody, finallyBody);
    }
}
